/* ------------------------------------------------------------------------------
 * Font metrics and text rendering
 * -------------------------------------------------------------------------- */

static const uint8_t font_blank_glyph[FONT_GLYPH_HEIGHT] = { 0 };

void font_init(void) {
    /* The font is a compile time constant: nothing to load at run time. */
}

int font_glyph_width(void) {
    return FONT_GLYPH_WIDTH;
}

int font_glyph_height(void) {
    return FONT_GLYPH_HEIGHT;
}

const uint8_t* font_get_glyph(char c) {
    unsigned char u = (unsigned char)c;
    if (u < FONT_FIRST_CHAR || u > FONT_LAST_CHAR) return font_blank_glyph;
    return font8x16_glyphs[u - FONT_FIRST_CHAR];
}

int font_text_width(const char* text) {
    if (!text || *text == '\0') return 0;

    int count = 0;
    for (const char* p = text; *p; p++) {
        if (*p == '\n') break;
        count++;
    }
    return count * FONT_GLYPH_WIDTH;
}

int font_text_height(const char* text) {
    if (!text || *text == '\0') return FONT_GLYPH_HEIGHT;

    int lines = 1;
    for (const char* p = text; *p; p++) {
        if (*p == '\n') lines++;
    }
    return lines * FONT_GLYPH_HEIGHT;
}

void draw_char(int x, int y, char c, uint32_t fg, uint32_t bg, int spacing) {
    const uint8_t* glyph = font_get_glyph(c);

    for (int row = 0; row < FONT_GLYPH_HEIGHT; row++) {
        uint8_t bits = glyph[row];
        for (int col = 0; col < FONT_GLYPH_WIDTH; col++) {
            if (bits & (0x80 >> col)) {
                graphics_put_pixel(x + col, y + row, fg);
            } else if (bg != FONT_TRANSPARENT) {
                graphics_put_pixel(x + col, y + row, bg);
            }
        }
    }

    if (spacing > 0 && bg != FONT_TRANSPARENT) {
        for (int i = 0; i < spacing; i++) {
            for (int row = 0; row < FONT_GLYPH_HEIGHT; row++) {
                graphics_put_pixel(x + FONT_GLYPH_WIDTH + i, y + row, bg);
            }
        }
    }
}

void draw_text(int x, int y, const char* text, uint32_t fg, uint32_t bg, int spacing) {
    if (!text) return;

    int cx = x;
    int cy = y;
    for (const char* p = text; *p; p++) {
        if (*p == '\n') {
            cx = x;
            cy += FONT_GLYPH_HEIGHT;
            continue;
        }
        draw_char(cx, cy, *p, fg, bg, spacing);
        cx += FONT_GLYPH_WIDTH + spacing;
    }
}

int draw_text_clipped(int x, int y, int max_width, const char* text, uint32_t fg, uint32_t bg, int spacing) {
    if (!text || max_width <= 0) return 0;

    int cx = x;
    int cy = y;
    int drawn = 0;
    for (const char* p = text; *p; p++) {
        if (*p == '\n') {
            cx = x;
            cy += FONT_GLYPH_HEIGHT;
            continue;
        }
        if (cx + FONT_GLYPH_WIDTH > x + max_width) break;
        draw_char(cx, cy, *p, fg, bg, spacing);
        cx += FONT_GLYPH_WIDTH + spacing;
        drawn++;
    }
    return drawn;
}

void draw_text_centered(int x, int y, int area_width, const char* text, uint32_t fg, uint32_t bg, int spacing) {
    int w = font_text_width(text);
    int offset = (area_width - w) / 2;
    if (offset < 0) offset = 0;
    draw_text(x + offset, y, text, fg, bg, spacing);
}
